function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // sun
  ctx.beginPath();
  ctx.arc(W / 2, H / 2, 50, 0, 2 * Math.PI);
  ctx.fillStyle = 'yellow';
  ctx.fill();
  ctx.stroke();

  // clouds
  for (let i = 0; i < 5; i++) {
    ctx.beginPath();
    ctx.arc(W / 2 + Math.sin(t + i) * 100, H / 2 + Math.cos(t + i) * 50, 20, 0, 2 * Math.PI);
    ctx.fillStyle = 'white';
    ctx.fill();
    ctx.stroke();
  }

  // tree
  ctx.beginPath();
  ctx.moveTo(W / 2, H);
  ctx.lineTo(W / 2, H - 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W / 2, H - 100, 50, 0, 2 * Math.PI);
  ctx.fillStyle = 'green';
  ctx.fill();
  ctx.stroke();

  // bird
  ctx.beginPath();
  ctx.arc(W / 2 + Math.sin(t) * 150, H / 2 + Math.cos(t) * 100, 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'black';
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W / 2 + Math.sin(t) * 150, H / 2 + Math.cos(t) * 100);
  ctx.lineTo(W / 2 + Math.sin(t) * 150 + Math.cos(t) * 20, H / 2 + Math.cos(t) * 100 + Math.sin(t) * 20);
  ctx.stroke();

  ctx.restore();
}
